-- 0167_invoicing_line_lots
-- Forward-only migration (rule 34). Covered by packages/modules/invoicing/src/__tests__/invoice-lots.integration.test.ts (the lots copied onto
-- the line and frozen at «Emitir», the «Lote / Vence / Serie» column of the masked view, the DIAN setting off by default and on behind
-- step-up) and entities.test.ts (the masked views below equal the ones generated from packages/modules/invoicing/src/entities.ts).
-- Plan 2B.2 Task 28.4 (PG §3.5, RG-5, owner items 149, 150):
--   * invoicing.invoice_lines.lots jsonb: the lots and serials a line bills, `[{ lotCode, expiresOn, serialNo, qty }]`, copied from sales'
--     published sales.v_invoice_delivery_lines.lots (0166) when the line is written from an entrega line; rewritten with the line at
--     «Emitir» and frozen there (the lines of an issued invoice are locked, 0092). Null for a line that bills no lot (RG-2).
--   * invoicing.settings.dian_item_instance boolean not null default false: write the lots and serials into the electronic invoice's XML
--     (cac:ItemInstance). Off until the accountant or a DIAN habilitación check confirms the validator accepts it (item 150). Written only
--     by invoicing.settings.update (step-up, admin only).
--   * Masked views (rule 14) re-created with the new columns appended: v_settings (dian_item_instance) and v_invoice_lines (lots, as text).

alter table invoicing.invoice_lines add column lots jsonb check (lots is null or jsonb_typeof(lots) = 'array');
alter table invoicing.settings add column dian_item_instance boolean not null default false;

-- ---------------------------------------------------------------------------------------------
-- Masked read views (rule 14), generated by maskedViewSql from packages/modules/invoicing/src/entities.ts and pasted here;
-- entities.test.ts fails when they drift.
-- ---------------------------------------------------------------------------------------------

